blocks.content:
1#signup-form {
2    background-color: #f9f9f9;
3    color: #333;
4    font-family: Arial, sans-serif;
5    font-size: 14px;
6    font-weight: bold;
7
8    width: clamp(250px, 30%, 400px);
9    padding: 20px;
10
11    border: 1px solid #ddd;
12    border-radius: 8px;
13
14    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
15}
16
17.form-group {
18    margin-bottom: 10px;
19}
20
21.signup-label {
22    display: block;
23    margin-bottom: 5px;
24}
25
26.signup-input {
27    box-sizing: border-box;
28    width: 100%;
29    padding: 10px;
30    border: 1px solid #ccc;
31    border-radius: 4px;
32}
33
34#submit-btn {
35    background-color: #007BFF;
36    color: white;
37    font-size: 16px;
38
39    width: 100%;
40    padding: 10px 15px;
41    border: none;
42    border-radius: 4px;
43
44    cursor: pointer;
45    transition: background-color 0.3s ease;
46}
47
48#submit-btn:hover {
49    background-color: #0056b3;
50}
51
52.login-checkbox {
53    font-style: italic;
54    font-weight: normal;
55
56    display: flex;
57    align-items: center;
58    margin-top: 20px;
59}
